contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool callAsOwner) public {
        require(newOwner != address(this));
        address initialOwner = c.owner();
        bool success;
        bool reverted;
        if (callAsOwner) {
            success = c.setOwner(newOwner);
        } else {
            try c.setOwner(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        address currentOwner = c.owner();
        if (callAsOwner) {
            assert(success && currentOwner == newOwner && initialOwner == address(this));
        } else {
            assert(reverted && currentOwner == initialOwner);
        }
    }
    receive() external payable {}
}

