contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        require(newOwner != address(this));
        require(msg.sender == address(this));
        // Deployer is this contract, so msg.sender == owner here; simulate a non-owner
        // by having the deciding call come from a different address is impossible,
        // so instead first transfer ownership away, then attempt from this contract
        // (now a non-owner) to the parameter address.
        require(newOwner != c.owner());
        c.setOwner(newOwner);
        address ownerBefore = c.owner();
        bool reverted;
        try c.setOwner(address(0x1)) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == ownerBefore);
    }
    receive() external payable { }
}

