contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address attacker, address newOwner) public {
        require(attacker != c.owner());
        address ownerBefore = c.owner();
        bool reverted;
        // simulate a non-owner call: c's only caller is this contract,
        // so set ownership away first, then attempt from a context where
        // msg.sender != owner is expressed by checking revert via a fresh owner
        // Since InvMutTest is msg.sender, make owner a different address:
        bool ok = c.setOwner(attacker);
        require(ok && attacker != address(this));
        address ownerMid = c.owner();
        try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.owner() == ownerMid && ownerMid == attacker && ownerBefore == ownerMid || !reverted && !ok);
    }
    receive() external payable {}
}
